import numpy as np

def infer_and_predict(A, colors=None, sym=False):
 arr=np.array(A); coords=np.argwhere(arr==1)
 r0,c0=coords.min(0); coords=coords-[r0,c0]
 h,w=coords.max(0)+1; base=np.zeros((h,w),int)
 for r,c in coords: base[r,c]=1
 shapes={}
 for k in (range(4) if sym else [0]):
  x=np.rot90(base,k)
  for y in ([x,np.fliplr(x)] if sym else [x]):
   p=tuple(map(tuple,np.argwhere(y)))
   shapes[(y.shape,p)]=y
 pred=arr.copy(); matches=[]
 for (hh,ww),p in shapes:
  for r in range(arr.shape[0]-hh+1):
   for c in range(arr.shape[1]-ww+1):
    vals=[arr[r+dr,c+dc] for dr,dc in p]
    if vals and len(set(vals))==1 and vals[0] in (colors or [0,3]):
     matches.append((r,c,(hh,ww),p))
     for dr,dc in p: pred[r+dr,c+dc]=1
 return pred,matches,shapes
